def post(xs, result):
    expected = []
    n = len(xs)
    i = 0
    while i < n:
        j = i
        while j < n and xs[j] == xs[i]:
            j += 1
        expected.append(xs[i])
        expected.append(j - i)
        i = j
    if len(result) != len(expected):
        return False
    for k in range(len(expected)):
        if result[k] != expected[k]:
            return False
    return True
